import{_ as n,o as e,c as t,a4 as s}from"./chunks/framework.B-wJupoK.js";const p="/assets/image-20260311185137117.C6RmIP53.png",o="/assets/image-20260311190000774.C06y80P3.png",r="/assets/image-20260311190448766.CKQoRecr.png",l="/assets/image-20260311190825197.7p55iWK6.png",i="/assets/image-20260311191539001.DLn8rBit.png",c="/assets/image-20260311191914124.BE3h3Lod.png",_="/assets/image-20260311192103818.2MHvGsXT.png",g="/assets/image-20260311200452437.DmwP8Pjf.png",y=JSON.parse('{"title":"为什么你的龙虾 openclaw 搜索网络资讯的技能不好用","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/为什么你的龙虾 openclaw 搜索网络资讯的技能不好用/为什么你的龙虾 openclaw 搜索网络资讯的技能不好用.md","filePath":"AI人工智能/为什么你的龙虾 openclaw 搜索网络资讯的技能不好用/为什么你的龙虾 openclaw 搜索网络资讯的技能不好用.md","lastUpdated":1773233117000,"__rawMarkdown":"# 为什么你的龙虾 openclaw 搜索网络资讯的技能不好用\\n\\n## 前言\\n\\n最近小伙伴在使用龙虾 openclaw 执行一些搜索网络资讯的服务时，发现被限制了频率。\\n\\n![](assets/image-20260311185137117.png)\\n\\n这个问题一方面可能是你对接的大模型的套餐的问题，就是超出套餐的频率了，比如最近比较多的一些 coding plan 套餐，一般都是 5 个小时 1200 次，超过了就会限速。\\n\\n![](assets/image-20260311190000774.png)\\n\\n另外一方面是因为 openclaw 内置的 web 工具有两个\\n\\n- 一个是 web_search：默认使用 **Brave Search API**，它会根据搜索内容帮你整理并且返回，比较智能和高效，目前是需要付费使用的。\\n\\n![](assets/image-20260311190448766.png)\\n\\n- 另一个是 web_fetch：使用 http 协议，相当于直接打开网页，但是网页内容还需要龙虾进一步提炼和分析。\\n\\n所以到这里你就知道为什么你的龙虾搜索网络资讯时，为什么不好用了吧？\\n\\n## 解决方案\\n\\n可以使用 **Tavily Web** 替代方案，它针对登录用户每月提供了 1000 Credits ，基本可以够普通用户体验使用。\\n\\n![](assets/image-20260311190825197.png)\\n\\n## 获取 key\\n\\n[注册和登录](https://app.tavily.com/home)\\n\\n然后获取你的专属的**key**。\\n\\n> tvly-dxxxxxxxx\\n\\n![](assets/image-20260311191539001.png)\\n\\n## 使用和配置\\n\\n然后回到你的小龙虾上，这样告诉它\\n\\n> 帮我安装 Tavily Web 这个技能，并且设置它为你默认的搜索技能，并且配置 Tavily Web 的 key: xxxxxxxxx\\n\\n**上面的 xxx 需要转换成你的 key**\\n\\n![image-20260311191914124](assets/image-20260311191914124.png)\\n\\n![](assets/image-20260311192103818.png)\\n\\n根据提示做回应即可，还是比较智能的。\\n\\n## 完工\\n\\n现在你可以继续使用联网的搜索服务了。\\n\\n![](assets/image-20260311200452437.png)\\n\\n\\n\\n## 总结\\n\\n\\n\\n万少建立了一个专门讨论小龙虾OpenClaw的微信群，大家可以互相交流和分享关于小龙虾生态的资讯消息。\\n\\n\\n\\n目前人已经超过200人了，私聊我进群。\\n\\n**关注我**，持续分享鸿蒙开发 + AI 提效的实战技巧。\\n\\n![](https://blog.zbztb.cn/assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg)"}'),m={name:"AI人工智能/为什么你的龙虾 openclaw 搜索网络资讯的技能不好用/为什么你的龙虾 openclaw 搜索网络资讯的技能不好用.md"};function h(x,a,d,b,u,w){return e(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="为什么你的龙虾-openclaw-搜索网络资讯的技能不好用" tabindex="-1">为什么你的龙虾 openclaw 搜索网络资讯的技能不好用 <a class="header-anchor" href="#为什么你的龙虾-openclaw-搜索网络资讯的技能不好用" aria-label="Permalink to &quot;为什么你的龙虾 openclaw 搜索网络资讯的技能不好用&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>最近小伙伴在使用龙虾 openclaw 执行一些搜索网络资讯的服务时，发现被限制了频率。</p><p><img src="'+p+'" alt=""></p><p>这个问题一方面可能是你对接的大模型的套餐的问题，就是超出套餐的频率了，比如最近比较多的一些 coding plan 套餐，一般都是 5 个小时 1200 次，超过了就会限速。</p><p><img src="'+o+'" alt=""></p><p>另外一方面是因为 openclaw 内置的 web 工具有两个</p><ul><li>一个是 web_search：默认使用 <strong>Brave Search API</strong>，它会根据搜索内容帮你整理并且返回，比较智能和高效，目前是需要付费使用的。</li></ul><p><img src="'+r+'" alt=""></p><ul><li>另一个是 web_fetch：使用 http 协议，相当于直接打开网页，但是网页内容还需要龙虾进一步提炼和分析。</li></ul><p>所以到这里你就知道为什么你的龙虾搜索网络资讯时，为什么不好用了吧？</p><h2 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h2><p>可以使用 <strong>Tavily Web</strong> 替代方案，它针对登录用户每月提供了 1000 Credits ，基本可以够普通用户体验使用。</p><p><img src="'+l+'" alt=""></p><h2 id="获取-key" tabindex="-1">获取 key <a class="header-anchor" href="#获取-key" aria-label="Permalink to &quot;获取 key&quot;">​</a></h2><p><a href="https://app.tavily.com/home" target="_blank" rel="noreferrer">注册和登录</a></p><p>然后获取你的专属的<strong>key</strong>。</p><blockquote><p>tvly-dxxxxxxxx</p></blockquote><p><img src="'+i+'" alt=""></p><h2 id="使用和配置" tabindex="-1">使用和配置 <a class="header-anchor" href="#使用和配置" aria-label="Permalink to &quot;使用和配置&quot;">​</a></h2><p>然后回到你的小龙虾上，这样告诉它</p><blockquote><p>帮我安装 Tavily Web 这个技能，并且设置它为你默认的搜索技能，并且配置 Tavily Web 的 key: xxxxxxxxx</p></blockquote><p><strong>上面的 xxx 需要转换成你的 key</strong></p><p><img src="'+c+'" alt="image-20260311191914124"></p><p><img src="'+_+'" alt=""></p><p>根据提示做回应即可，还是比较智能的。</p><h2 id="完工" tabindex="-1">完工 <a class="header-anchor" href="#完工" aria-label="Permalink to &quot;完工&quot;">​</a></h2><p>现在你可以继续使用联网的搜索服务了。</p><p><img src="'+g+'" alt=""></p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>万少建立了一个专门讨论小龙虾OpenClaw的微信群，大家可以互相交流和分享关于小龙虾生态的资讯消息。</p><p>目前人已经超过200人了，私聊我进群。</p><p><strong>关注我</strong>，持续分享鸿蒙开发 + AI 提效的实战技巧。</p><p><img src="https://blog.zbztb.cn/assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg" alt=""></p>',34)])])}const B=n(m,[["render",h]]);export{y as __pageData,B as default};
